PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE ai_agent_logs (
      id TEXT PRIMARY KEY,
      agent_id TEXT NOT NULL,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
      prompt_tokens INTEGER DEFAULT 0,
      completion_tokens INTEGER DEFAULT 0,
      execution_time_ms INTEGER DEFAULT 0,
      estimated_cost_usd REAL DEFAULT 0,
      business_value_score INTEGER DEFAULT 0,
      context_summary TEXT
    );
CREATE TABLE campaigns (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      status TEXT DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE ceo_actions (
      action_id TEXT PRIMARY KEY,
      action_type TEXT NOT NULL,
      status TEXT NOT NULL,
      reasoning TEXT,
      proposed_payload JSON,
      ledger JSON DEFAULT '[]',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE clients (
      id TEXT PRIMARY KEY,
      green_invoice_id TEXT UNIQUE,
      name TEXT NOT NULL,
      tax_id TEXT,
      email TEXT,
      phone TEXT,
      status TEXT DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE domains (
      id TEXT PRIMARY KEY,
      domain_name TEXT NOT NULL UNIQUE,
      registrar TEXT,
      expiry_date DATE,
      is_active INTEGER DEFAULT 1,
      status TEXT DEFAULT 'ok',
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE generic_documents (
      id TEXT PRIMARY KEY,
      collection TEXT NOT NULL,
      data JSON NOT NULL,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE invoices (
      id TEXT PRIMARY KEY,
      client_id TEXT,
      amount REAL NOT NULL,
      status TEXT DEFAULT 'unpaid',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY(client_id) REFERENCES clients(id)
    );
CREATE TABLE leads (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      email TEXT,
      phone TEXT,
      status TEXT DEFAULT 'new',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE meetings (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      date DATETIME NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE projects (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      client_id TEXT,
      status TEXT DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY(client_id) REFERENCES clients(id)
    );
CREATE TABLE quotes (
      id TEXT PRIMARY KEY,
      quote_number TEXT UNIQUE NOT NULL,
      client_id TEXT,
      total_amount REAL NOT NULL,
      status TEXT CHECK(status IN ('draft', 'sent', 'signed', 'cancelled')) DEFAULT 'draft',
      signature_data TEXT,
      signed_at DATETIME,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY(client_id) REFERENCES clients(id)
    );
CREATE TABLE ssh_checks (
      id TEXT PRIMARY KEY,
      domain_name TEXT NOT NULL,
      host TEXT NOT NULL,
      port INTEGER DEFAULT 22,
      status TEXT CHECK(status IN ('ok', 'error')) DEFAULT 'ok',
      last_check DATETIME DEFAULT CURRENT_TIMESTAMP,
      error_log TEXT
    );
CREATE TABLE suppliers (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      contact_info TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE system_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      event_type TEXT NOT NULL,
      target TEXT NOT NULL,
      details TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE tasks (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT,
      status TEXT DEFAULT 'todo',
      project_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY(project_id) REFERENCES projects(id)
    );
