CREATE TABLE users (
      id TEXT PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      role TEXT DEFAULT 'user',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE INDEX idx_gen_docs_coll ON generic_documents(collection);
CREATE INDEX idx_gen_docs_coll_id ON generic_documents(collection, id);
CREATE INDEX idx_gen_docs_updated ON generic_documents(collection, updated_at DESC);
CREATE INDEX idx_quotes_client ON quotes(client_id);
CREATE INDEX idx_system_logs_type ON system_logs(event_type, id DESC);
CREATE INDEX idx_ssh_checks_domain ON ssh_checks(domain_name, last_check DESC);
DELETE FROM "sqlite_sequence";
